-- Zipun MySQL schema for XAMPP
CREATE DATABASE IF NOT EXISTS zipun CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE zipun;
CREATE TABLE IF NOT EXISTS users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, username VARCHAR(50) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS lessons (id INT PRIMARY KEY, title VARCHAR(255) NOT NULL, week TINYINT UNSIGNED DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS vocab (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, lesson_id INT NOT NULL, jp VARCHAR(255) NOT NULL, kana VARCHAR(255), romaji VARCHAR(255), meaning TEXT, UNIQUE KEY uq_vocab_lesson (lesson_id, jp, kana), CONSTRAINT fk_vocab_lesson FOREIGN KEY (lesson_id) REFERENCES lessons(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS user_vocab_progress (user_id INT UNSIGNED NOT NULL, vocab_id INT UNSIGNED NOT NULL, ease DECIMAL(5,2) NOT NULL DEFAULT 2.50, interval_days DECIMAL(10,2) NOT NULL DEFAULT 0, reps INT NOT NULL DEFAULT 0, lapses INT NOT NULL DEFAULT 0, next_review DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, memorized TINYINT(1) NOT NULL DEFAULT 0, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (user_id, vocab_id), CONSTRAINT fk_progress_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, CONSTRAINT fk_progress_vocab FOREIGN KEY (vocab_id) REFERENCES vocab(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS study_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, study_date DATE NOT NULL, xp INT NOT NULL DEFAULT 0, minutes INT NOT NULL DEFAULT 0, correct INT NOT NULL DEFAULT 0, total INT NOT NULL DEFAULT 0, UNIQUE KEY uq_log (user_id, study_date), CONSTRAINT fk_log_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
